// Some portions generated by Claude Code
package org.eclipse.rdf4j.query.impl;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.List;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.Binding;
import org.eclipse.rdf4j.query.BindingSetTest;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link MapBindingSet}
 *
 * @author Jeen Broekstra
 */
public class MapBindingSetTest extends BindingSetTest<MapBindingSet> {

	@Override
	protected MapBindingSet[] createTwoEqualReorderedBindingSets() {

		MapBindingSet bindingSet1 = new MapBindingSet();
		MapBindingSet bindingSet2 = new MapBindingSet();

		bindingSet1.addBinding("x", RDF.ALT);
		bindingSet1.addBinding("y", RDF.BAG);
		bindingSet1.addBinding("z", RDF.FIRST);

		bindingSet2.addBinding("y", RDF.BAG);
		bindingSet2.addBinding("x", RDF.ALT);
		bindingSet2.addBinding("z", RDF.FIRST);

		return new MapBindingSet[] { bindingSet1, bindingSet2 };
	}

	private static MapBindingSet plain() {
		MapBindingSet expected = new MapBindingSet();
		expected.addBinding("x", RDF.ALT);
		expected.addBinding("z", RDF.FIRST);
		return expected;
	}

	private static MapBindingSet compact(Value[] values) {
		return new MapBindingSet.CompactLayout(new String[] { "x", "y", "z" }).snapshot(values, 2);
	}

	@Test
	public void compactSnapshotAnswersLikeAnOrdinaryBindingSet() {
		MapBindingSet snapshot = compact(new Value[] { RDF.ALT, null, RDF.FIRST });

		assertEquals(2, snapshot.size());
		assertSame(RDF.ALT, snapshot.getValue("x"));
		assertSame(RDF.FIRST, snapshot.getValue(new String("z")));
		assertNull(snapshot.getValue("y"));
		assertNull(snapshot.getValue("unknown"));
		assertTrue(snapshot.hasBinding("x"));
		assertFalse(snapshot.hasBinding("y"));
		assertFalse(snapshot.hasBinding("unknown"));
		Binding binding = snapshot.getBinding("z");
		assertEquals("z", binding.getName());
		assertSame(RDF.FIRST, binding.getValue());
		assertSame(binding, snapshot.getBinding("z"));
		assertNull(snapshot.getBinding("y"));

		assertEquals(plain(), snapshot);
		assertEquals(snapshot, plain());
		assertEquals(plain().hashCode(), snapshot.hashCode());
		assertEquals(List.of("x", "z"), List.copyOf(snapshot.getBindingNames()));
	}

	@Test
	public void changingACompactSnapshotLeavesItsValueArrayAlone() {
		Value[] values = { RDF.ALT, null, RDF.FIRST };
		MapBindingSet first = compact(values);
		MapBindingSet second = compact(values);

		first.addBinding("y", RDF.BAG);
		first.setBinding("x", RDF.REST);
		first.removeBinding("z");
		first.removeBinding("unknown");
		assertEquals(2, first.size());
		assertSame(RDF.REST, first.getValue("x"));
		assertSame(RDF.BAG, first.getValue("y"));
		assertFalse(first.hasBinding("z"));

		assertSame(RDF.ALT, values[0]);
		assertNull(values[1]);
		assertSame(RDF.FIRST, values[2]);
		assertEquals(plain(), second);

		second.clear();
		assertEquals(0, second.size());
		assertFalse(second.iterator().hasNext());
		assertSame(RDF.FIRST, values[2]);
	}

	@Test
	public void removingAnUnboundNameKeepsACompactSnapshotCompact() {
		MapBindingSet snapshot = compact(new Value[] { RDF.ALT, null, RDF.FIRST });
		snapshot.removeBinding("y");
		snapshot.removeBinding("unknown");
		assertEquals(plain(), snapshot);
	}

	@Test
	public void compactSnapshotIsSerializedAsAnOrdinaryBindingSet() throws Exception {
		MapBindingSet snapshot = compact(new Value[] { RDF.ALT, null, RDF.FIRST });
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
			out.writeObject(snapshot);
			out.writeObject(plain());
		}
		try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			Object fromSnapshot = in.readObject();
			Object fromPlain = in.readObject();
			assertSame(MapBindingSet.class, fromSnapshot.getClass());
			assertEquals(plain(), fromSnapshot);
			assertEquals(fromPlain, fromSnapshot);
			((MapBindingSet) fromSnapshot).addBinding("y", RDF.BAG);
			assertEquals(3, ((MapBindingSet) fromSnapshot).size());
		}
		assertEquals(plain(), snapshot);
	}

	@Test
	public void wideCompactLayoutFindsEveryName() {
		String[] names = new String[20];
		Value[] values = new Value[20];
		for (int i = 0; i < names.length; i++) {
			names[i] = "v" + i;
			values[i] = i % 2 == 0 ? RDF.ALT : RDF.BAG;
		}
		MapBindingSet snapshot = new MapBindingSet.CompactLayout(names).snapshot(values, values.length);
		for (int i = 0; i < names.length; i++) {
			assertSame(values[i], snapshot.getValue("v" + i));
		}
		assertNull(snapshot.getValue("v20"));
		assertEquals(20, snapshot.size());
	}

}
